"""FastAPI application factory for the embedded server.Deliberately **lifespan-free**. ``main.py`` owns the event loop, constructsevery singleton, and runs this app through``uvicorn.Server(uvicorn.Config(app)).serve()`` as one task among several. AFastAPI lifespan here would create a second, competing ownership of the storeand the broadcaster, and on shutdown the two teardown paths would race: thelifespan would close a broadcaster the composition root was still using, orvice versa.So this factory only ever *receives* wired instances and hangs them on``app.state``. It constructs nothing with a lifecycle."""from __future__ import annotationsfrom typing import Any, Finalimport structlogfrom fastapi import FastAPI, Request, statusfrom fastapi.middleware.cors import CORSMiddlewarefrom fastapi.responses import JSONResponsefrom betdoc.adapters.cache.state_store import InMemoryStateStorefrom betdoc.presentation.api.broadcaster import WebsocketBroadcasterfrom betdoc.presentation.api.routers import intelligence, stream__all__ = ["build_api"]_log: Final[structlog.stdlib.BoundLogger] = structlog.get_logger(component="presentation.api.app")_API_TITLE: Final[str] = "BetDoc Advisor API"_API_VERSION: Final[str] = "1.0.0"def build_api(    store: InMemoryStateStore,    broadcaster: WebsocketBroadcaster,    *,    profile_id: str = "primary",    allowed_origins: tuple[str, ...] = ("*",),    enable_docs: bool = True,) -> FastAPI:    """Build the read-only presentation app over already-wired singletons.    Args:        store: The live L1 cache. Must be the same instance the refresh daemon            writes to, otherwise every endpoint reports an empty cache while            the engine trades normally.        broadcaster: The same instance wired into the ``CompositeNotifier``.        profile_id: Active profile, read by the dependency layer.        allowed_origins: CORS origins. ``("*",)`` is correct for a local            dashboard and must be narrowed before this is ever exposed beyond            localhost.        enable_docs: Serve ``/docs`` and ``/redoc``.    Returns:        A configured :class:`FastAPI` app with no lifespan and no background        tasks of its own.    """    app = FastAPI(        title=_API_TITLE,        version=_API_VERSION,        description=(            "Read-only projection of the BetDoc advisor. No endpoint in this "            "API can place a bet, change a limit, or mutate engine state."        ),        docs_url="/docs" if enable_docs else None,        redoc_url="/redoc" if enable_docs else None,        openapi_url="/openapi.json" if enable_docs else None,        lifespan=None,    )    # Singletons, not factories. The API borrows what main.py owns.    app.state.store = store    app.state.broadcaster = broadcaster    app.state.profile_id = profile_id    # Wildcard CORS with credentials disabled. The browser refuses the    # combination of "*" with allow_credentials=True anyway, and enabling    # credentials on a wildcard origin would be the wrong trade regardless.    app.add_middleware(        CORSMiddleware,        allow_origins=list(allowed_origins),        allow_credentials=False,        allow_methods=["GET", "OPTIONS"],        allow_headers=["*"],        expose_headers=["X-BetDoc-Version"],        max_age=600,    )    app.include_router(intelligence.router)    app.include_router(stream.router)    @app.get("/health", tags=["system"], summary="Liveness probe")    async def health() -> dict[str, Any]:        """Liveness only. Deliberately does not touch the store.        A liveness probe that inspects dependencies will fail during a        transient cache miss and get the process restarted, which turns a        recoverable degradation into an outage. Readiness lives at        ``/api/v1/intelligence/health``, where it belongs.        """        return {"status": "ok", "service": "betdoc-advisor", "version": _API_VERSION}    @app.get("/ready", tags=["system"], summary="Readiness probe")    async def ready(request: Request) -> JSONResponse:        """Ready once the cache is warm and the broadcaster is wired.        Returns 503 while cold, so an orchestrator holds traffic back rather        than routing to a process that would answer every query with an empty        projection.        """        cache: InMemoryStateStore = request.app.state.store        caster: WebsocketBroadcaster = request.app.state.broadcaster        is_ready = cache.is_warm        return JSONResponse(            status_code=(status.HTTP_200_OK if is_ready else status.HTTP_503_SERVICE_UNAVAILABLE),            content={                "ready": is_ready,                "cache_warm": cache.is_warm,                "websocket_clients": caster.client_count,            },        )    @app.middleware("http")    async def add_version_header(request: Request, call_next: Any) -> Any:        response = await call_next(request)        response.headers["X-BetDoc-Version"] = _API_VERSION        return response    _log.info(        "api.built",        version=_API_VERSION,        docs_enabled=enable_docs,        allowed_origins=list(allowed_origins),        routes=len(app.routes),    )    return app